# Pkg.add("DelimitedFiles")

using HyperModularity
using SimpleHypergraphs 
using DelimitedFiles
using ArgParse


include("AON_HMLL_auxiliary.jl")

######
function parse_commandline()
    s = ArgParse.ArgParseSettings()

    ArgParse.@add_arg_table! s begin
        "-d"
            arg_type = String
            default = "./"
            help = "data directory"
        "-m"
            arg_type = String
            required = true
            help = "generating model"
        "-s"
            arg_type = String
            required = true
            help = "scenario (parameter choice)"
        "-n"
            arg_type = Int64
            default = 25
            help  = "num of hypergraphs in the scenario"
        "-t"
            arg_type = Int64
            required = true
            help  = "number of threads"
        
    end
    s.usage = "julia AON_HMLL_script.jl -d data_root_dir -m mod -s scen -n N -t T"

    return ArgParse.parse_args(s)
end
######

# exemple of a command
# julia AON_HMLL_script.jl -d "survey_benchmark/" -m "HyperSBM/" -s "scenA1/" -n 25 - t 4
# julia AON_HMLL_script.jl -d "survey_benchmark/" -m "DCHSBM/" -s "scenA1/" -n 25 -t 4



#######################
#######################
function main()
    parsed_args = parse_commandline()
    
    ###### PARSE ARGUMENTS ######
    data_root_dir = parsed_args["d"]
    cd(data_root_dir)
    model = parsed_args["m"]
    scenario = parsed_args["s"]
    nreps =  parsed_args["n"]
    nthreads = parsed_args["t"]

    
    ###### INITIALIZATIONS OF VARIABLES ######
    Ari = zeros(Float64, nreps)
    runtimes = zeros(Float64, nreps)
    Q = zeros(Float64, nreps)
    Q_true = zeros(Float64, nreps)
    K_true = zeros(Int64, nreps)
    K_hat = zeros(Int64, nreps)
    conductance_hat = zeros(Float64, nreps)

    ###### GET RUNNING TIMES & CONDUCTANCES ######
    filename = string(model,scenario,"mt_kahypar_results_$(nthreads)threads.results.t_c")
    lines = readlines(filename)
    # times are in line "Time (sec.) = [t1, t2, ..., tn]"
    times_str = split(split(lines[1], "=")[2], "[")[2]
    times_str = split(times_str, "]")[1]
    times = split(times_str, ",")
    runtimes = parse.(Float64, times)
    # conductance_hat are in line "Conductance = [c1, c2, ..., cn]"
    conductance_str = split(split(lines[2], "=")[2], "[")[2]
    conductance_str = split(conductance_str, "]")[1]
    conductances = split(conductance_str, ",")
    conductance_hat = parse.(Float64, conductances)

    ###### LOOP OVER DATASETS ######
    for i in 1:nreps
        print("\n Number of iteration: $i")
        
        # read true label vector
        filename = string(model,scenario,"rep",i,"_assign.txt")
        Z_true = vec(readdlm(filename, Int))
        Z_hat = vec(readdlm(string(model,scenario,"mt_kahypar_rep",i,"_he.hgr_",nthreads,"threads.part"), Int))
        Z_hat .+= 1  # add 1 to each element of Z_hat
        K_true[i] = length(unique(Z_true)) # true number of clusters
        K_hat[i]= length(unique(Z_hat)) # estimated number of clusters

        # read data
        filename = string(model,scenario,"rep",i)
        E = read_hypergraph_edges(filename) # possible to add min and max hyperedge size
        n = maximum([maximum(e) for k in keys(E) for e in keys(E[k])])
        D = zeros(Int64, n)
        for (sz, edges) in E
            for (e, _) in edges
                D[e] .+= 1
            end
        end
        maxedges = maximum(keys(E))
        for k in 1:maxedges
            if !haskey(E, k)
                E[k] = Dict{}()
            end
        end
        # construct hypergraph
        N = 1:n
        H = hypergraph(N, E, D)
        
        ######## Extract omega parameters to compute modularity ######
        # compute initialisation corresponding to startclusters = "cliquelouvain"
        Z0 = HyperModularity.CliqueExpansionModularity(H,1.0) # default value gamma=1.0
        He2n, weights = HyperModularity.hypergraph2incidence(H)
        e2n = incidence2elist(He2n)
        d = 1.0*H.D # degree vector - coercion to float for compatibility with AON_louvain
        β, γ,omega = learn_omega_aon(e2n,weights,Z0,maxedges,d,n)
        
        Q[i] = modularity_aon(H,Z_hat,omega)
        Q_true[i] = modularity_aon(H,Z_true,omega)
       
        ######### Compute ARI #######
        Ari[i] = ari(Z_hat,Z_true)
        
        # save partial results
        filename= string(model,scenario,"mt_kahypar_results_$(nthreads)threads.results")
        open(filename, "w") do f
            write(f, "ARI=$(string(Ari))"*"\n"*"CPU time = $runtimes"*"\n"*"Modularity = $Q"*"\n"*"GT_Mod = $Q_true"*"\n"*"K_hat = $K_hat"*"\n"*"K_true = $K_true\n"*"Conductance = $conductance_hat")
        end
    end
end


##################
##################
main()